/bin/bash -lc "node --input-type=module <<'NODE'
import assert from 'node:assert/strict'
import http from 'node:http'
import net from 'node:net'
import { spawn } from 'node:child_process'
import { once } from 'node:events'

const pending = []
const events = []
const analytics = http.createServer(async (req, res) => {
  let body = ''
  for await (const chunk of req) body += chunk
  events.push({ method: req.method, body: JSON.parse(body) })
  pending.push(res)
})
await new Promise(resolve => analytics.listen(0, '127.0.0.1', resolve))
const portProbe = net.createServer()
await new Promise(resolve => portProbe.listen(0, '127.0.0.1', resolve))
const appPort = portProbe.address().port
await new Promise(resolve => portProbe.close(resolve))
const app = spawn(process.execPath, ['node_modules/next/dist/bin/next', 'start', '-p', String(appPort), '-H', '127.0.0.1'], {
  env: { ...process.env, NEXT_TELEMETRY_DISABLED: '1', ANALYTICS_ENDPOINT: "'`http://127.0.0.1:${analytics.address().port}/events` },
  stdio: ['"'ignore', 'pipe', 'pipe'],
})
let output = ''
app.stdout.on('data', chunk => { output += chunk })
app.stderr.on('data', chunk => { output += chunk })
async function until(check, description) {
  const deadline = Date.now() + 10000
  while ("'!check()) {
    if (Date.now() > deadline) throw new Error(`Timed out: ${description}'"\\n"'${output}`)
    await new Promise(resolve => setTimeout(resolve, 25))
  }
}
try {
  await until(() => output.includes('"'Ready in'), 'app startup')
  for (let i = 0; i < 2; i++) {
    const response = await fetch("'`http://127.0.0.1:${appPort}`, { signal: AbortSignal.timeout(3000) })
    const html = await response.text()
    assert.equal(response.status, 200)
    assert.match(html, /<h1>Welcome<'"\\/h1>/)
    await until(() => events.length === i + 1, 'analytics request')
    assert.equal(pending[i].writableEnded, false, 'Page must arrive before analytics finishes')
    assert.equal(events[i].method, 'POST')
    assert.equal(events[i].body.event, 'page_view')
    assert.equal(events[i].body.path, '/')
    assert.ok(Number.isFinite(Date.parse(events[i].body.timestamp)))
    pending[i].writeHead(i === 0 ? 204 : 500)
    pending[i].end()
  }
  await until(() => output.includes('Failed to log page view:') && output.includes('Analytics service returned 500'), 'analytics error handling')
  console.log('PASS: Both visits return welcome HTML before analytics completes; each sends a page_view event; analytics failures are caught and logged.')
} finally {
  for (const res of pending) if ("'!res.writableEnded) res.end()
  app.kill('"'SIGTERM')
  await once(app, 'exit')
  analytics.closeAllConnections()
  await new Promise(resolve => analytics.close(resolve))
}
NODE"

